<?php
require_once __DIR__.'/bootstrap.php';
$db=Yii::app()->db;$pack=dirname(__DIR__).'/public/assets/storefront';$media=array();
foreach(glob($pack.'/*.webp') as $path){$key=pathinfo($path,PATHINFO_FILENAME);$name='storefront-'.$key.'.webp';$row=$db->createCommand('SELECT * FROM media WHERE original_name=:name')->queryRow(true,array(':name'=>$name));$media[$key]=$row?:MediaService::ingest($path,$name);}
if(!isset($media['product-lamp'])){echo "No storefront asset pack; CMS sample skipped.\n";return;}
if(ShopSettings::get('cms_demo_version')==='1'){echo "CMS sample already installed.\n";return;}
$tx=$db->beginTransaction();try{
 $products=array();foreach(array('LAMP-101'=>'lamp','VASE-102'=>'vase','WOOD-103'=>'wood','CLOCK-104'=>'clock','MUG-105'=>'mug','BOX-106'=>'box') as $sku=>$key){$p=Product::model()->findByAttributes(array('sku'=>$sku));if(!$p)continue;$products[]=$p->id;$db->createCommand()->delete('product_images','product_id=:id',array(':id'=>$p->id));$db->createCommand()->insert('product_images',array('product_id'=>$p->id,'filename'=>$media['product-'.$key]['filename'],'alt_text'=>$p->title,'sort_order'=>0));}
 foreach(array('home-decor'=>'vase','lifestyle'=>'mug','featured'=>'wood') as $slug=>$key){$cat=Category::model()->findByAttributes(array('slug'=>$slug));if(!$cat)continue;if(!$cat->image)$db->createCommand()->update('categories',array('image'=>$media['product-'.$key]['filename'],'description'=>'انتخاب‌هایی برای '. $cat->name),'id=:id',array(':id'=>$cat->id));if($slug==='home-decor'){foreach(array('lighting'=>array('روشنایی','lamp',array('LAMP-101')),'decor-objects'=>array('اشیای دکوراتیو','vase',array('VASE-102','CLOCK-104'))) as $childSlug=>$info){$child=Category::model()->findByAttributes(array('slug'=>$childSlug));if(!$child){$child=new Category;$child->name=$info[0];$child->slug=$childSlug;$child->parent_id=$cat->id;$child->image=$media['product-'.$info[1]]['filename'];$child->description='جزئیات هماهنگ برای فضای خانه';if(!$child->save())throw new Exception('Category seed failed');}foreach($info[2] as $sku)$db->createCommand()->update('products',array('category_id'=>$child->id),'sku=:sku',array(':sku'=>$sku));}}}
 $collection=ProductCollection::model()->findByAttributes(array('slug'=>'everyday-selection'));if(!$collection){$collection=new ProductCollection;$collection->title='انتخاب‌های روزمره';$collection->slug='everyday-selection';$collection->description='کالکشنی از اشیای ساده، کاربردی و ماندگار.';$collection->image=$media['hero-editorial-light']['filename'];$collection->is_active=1;if(!$collection->save())throw new Exception('Collection seed failed');foreach($products as $position=>$id)$db->createCommand()->insert('collection_products',array('collection_id'=>$collection->id,'product_id'=>$id,'position'=>$position));}
 $db->createCommand()->update('theme_blocks',array('collection_id'=>$collection->id),"block_type='collection' AND collection_id IS NULL");
 foreach(array('simple-home-decor'=>'hero-editorial-light','practical-gift-guide'=>'hero-editorial-dark') as $slug=>$key)$db->createCommand()->update('posts',array('cover_image'=>$media[$key]['filename']),'slug=:slug',array(':slug'=>$slug));
 ShopSettings::set('cms_demo_version','1');$tx->commit();echo "CMS collections, category tree and artwork installed.\n";
}catch(Exception $e){if($tx->active)$tx->rollback();throw $e;}
